using System.Linq; using common.resources; using wServer.realm.entities;
namespace wServer.realm.worlds.logic { class StarfallObservatory:World { Enemy boss; int wings; bool done,populated; readonly int[] active; public StarfallObservatory(ProtoWorld p,wServer.networking.Client c=null):base(p){var r=new System.Random(Id);active=new[]{r.Next(3),r.Next(3)}.Distinct().ToArray();if(active.Length<2)active=new[]{0,1};DungeonAnomalyService.Attach(this,DungeonAnomalyService.Roll(DungeonCodexService.All.FirstOrDefault(x=>x.Key=="StarfallObservatory"),r));} public override int EnterWorld(Entity e){var id=base.EnterWorld(e);if(e is Player&&!populated){populated=true;foreach(var w in active){Spawn("Astral Wing Guardian",2+w*3,3);Spawn("Constellation Wing Seal",2+w*3,6);}Spawn("The Parallax",5,8);}var n=e as Enemy;if(n==null)return id;n.OnDeath+=(s,a)=>Dead(n);if(n.ObjectDesc.ObjectId=="The Parallax"){boss=n;boss.ApplyConditionEffect(ConditionEffectIndex.Invincible);}return id;}void Spawn(string n,float x,float y){var e=Entity.Resolve(Manager,n);if(e!=null){e.Move(x,y);EnterWorld(e);}}void Dead(Enemy e){if(e.ObjectDesc.ObjectId=="Constellation Wing Seal"&&++wings>=2&&boss!=null)boss.ApplyConditionEffect(ConditionEffectIndex.Invincible,0);if(e.ObjectDesc.ObjectId=="The Parallax"&&!done){done=true;DungeonAnomalyService.Cleanup(this);foreach(var p in Players.Values){MaterialVaultService.TryDeposit(p.Client.Account,"citadel_fragment",1,"parallax:"+Id+":"+p.Client.Account.AccountId);p.SendInfo("Starfall Observatory cleared. Wings: "+string.Join(",",active));}}} } }
